Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
Ltac accok_fp_on ::= fail.
(* [comment removed for export] *)
Ltac tlia ::= sf_clear_big;
              first [ zify_prune_sub; Zify.zify; xlia zchecker
                    | Zify.zify; xlia zchecker
                    | sf_unhide;
                      first [ unpark_all; zify_prune_sub; Zify.zify; xlia zchecker
                            | zify_prune_neg; Zify.zify; xlia zchecker
                            | zify_prune_plain; Zify.zify; xlia zchecker
                            | Zify.zify; xlia zchecker ] ].
(* [comment removed for export] *)
Ltac lia ::= first [ zify_prune_sub; Zify.zify; xlia zchecker
                   | zify_prune; first [ zify_noeuclid; Z.euclidean_division_equations_cleanup; xlia zchecker | Zify.zify; xlia zchecker ]
                   | Zify.zify; xlia zchecker ].

(* [comment removed for export] *)
Ltac stk_acc RT AF pv :=
  lazymatch goal with
  | |- cps _ (ASTA RT ?S _ (eq (MS _ _ _ _ _ ?mc _))) _ =>
      lazymatch goal with
      | _ : acc asegs mc pv 4 |- _ => idtac
      | A : ART RT S mc |- _ =>
          let AC := fresh "ACCV" in
          assert (AC : acc asegs mc pv 4)
            by (apply (af_acc_stack RT AF S mc pv 4 A); repeat match goal with H : rt_sp0 _ _ = _ |- _ => rewrite H end; ul)
      end
  end.
Ltac lit_pc := lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 ?p) _ _ _ _) => let v := eval vm_compute in p in change p with v end.
Ltac at_pc := lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 ?p) _ _ _ _) => idtac "AT" p | |- evt _ _ (MS _ _ ?p _ _ _ _) => idtac "AT-IF" p
                                  | |- cps _ (ASTA _ _ _ (eq (MS _ _ (Z_to_bv 64 ?p) _ _ _ _))) _ => idtac "CPS-AT" p | |- ?g => idtac "STUCK-AT:" g end.
(* [comment removed for export] *)
Ltac fs_agree_tac2 :=
  first
    [ apply fs_agree_refl
    | assumption
    | let r := fresh "r" in let Hr := fresh "Hr" in
      intros r Hr; apply fs_callee_cases in Hr; cbn [map In] in Hr;
      repeat (destruct Hr as [<-|Hr]); [..| destruct Hr];
      repeat (rewrite ?fs_reg_get_set; fs_eqb_simp;
              first [ reflexivity
                    | match goal with H : fs_agree ?F1 ?F2 |- context [reg_get ?F2 ?rr] => rewrite (fs_agree_get F1 F2 rr H) by reflexivity end ]);
      reflexivity ].

(* [comment removed for export] *)
Ltac lres_udd LVP :=
  unfold lres; repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end;
  repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H end;
  cbn [length app]; unfold FRAMES_MAX, LIVE_MAX, UDD_COST, MCS_COST, HMT_COST, CASC_COST, CSC_COST, RC1, RASTER_COST in *;
  split; [repeat match goal with H : context [length (rt_frames _ _)] |- _ => revert H end; clear; intros; lia|];
  split; [repeat match goal with H : context [length (rt_live _ _)] |- _ => revert H end; clear; intros; lia|];
  split; [repeat match goal with H : context [rt_credit _ _] |- _ => revert H end; clear; intros; lia|];
  let p := fresh "p" in let n := fresh "n" in let Hn := fresh "Hn" in intros p n Hn; cbn [In] in Hn;
  repeat (destruct Hn as [Hn|Hn]; [injection Hn as <- <-; clear; lia |]); exact (LVP _ _ Hn).
Ltac sec_udd SECB :=
  repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H end;
  rewrite ?sec_bytes_cons_small by (clear; lia); unfold UDD_SECB, MCS_SECB, CSC_SECB in *; clear - SECB; lia.

Section OCC.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis LSTD : lept_stderr_cpsF RT.
Hypothesis RERR : returnError_cpsF RT e_returnErrorPtr.
Hypothesis LIT1 : exists l, In (A_OC_ERRMSG, l) LEPT_LITS.
Hypothesis LIT2 : exists l, In (A_OC_PROC, l) LEPT_LITS.
Hypothesis UDD : pixUpDownDetect2_cps RT.
Hypothesis R90 : pixRotate90_cps RT.
Hypothesis DES : pixDestroy_cpsF RT.
Hypothesis MOD : makeOrientDecision2_cps RT.
Hypothesis ORTH : pixRotateOrth_cps RT.
Hypothesis PCPY : pixCopyNew1_sure_cps RT.

Lemma oc_c16 : pixOrientCorrect2_case RT 16.
Proof using AF GP FKC LSTD RERR LIT1 LIT2 UDD R90 DES MOD ORTH PCPY.
ltac2:(KReplay.run1 (kr_t_Po_oc_c16 ()) ["OCC"] (String.concat "" [kr_b_Po_oc_c16_1_1 (); kr_b_Po_oc_c16_1_2 ()])). Qed.
End OCC.
